/// <summary>
/// PricingAttribute of table <c>PdsCatchWeightItem</c> field ItemId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributePdsCatchWeightItemItemId extends UPSPricingAttributePdsCatchWeightItem implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(PdsCatchWeightItem, ItemId);
}

public Set getAllowedValues()
{
    var                ret = new Set(Types::String);
    PdsCatchWeightItem pdsCatchWeightItem;

    while select pdsCatchWeightItem
        group by ItemId
    {
        if (! ret.in(pdsCatchWeightItem.ItemId))
        {
            ret.add(pdsCatchWeightItem.ItemId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(PdsCatchWeightItem, ItemId));
    qbr.value(queryValue(_value));
}
